  var ov = document.createElement("div");
  ov.style.cssText =
    "position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.88);" +
    "display:none;align-items:center;justify-content:center;z-index:99999;" +
    "cursor:zoom-out;padding:2vmin;";
