    "box-shadow:none !important;background:transparent;object-fit:contain;";
  ov.appendChild(big);
  function close() { ov.style.display = "none"; big.removeAttribute("src"); }
  ov.addEventListener("click", close);
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape") { close(); }
  });
  function attach() {
    if (!document.body) { return; }
    if (!ov.parentNode) { document.body.appendChild(ov); }
    document.addEventListener("click", function (e) {
      var t = e.target;
      if (!t || t.tagName !== "IMG" || t === big) { return; }
      big.src = t.currentSrc || t.src;
