Architecture.css:
/* Architecture */
:root {
  --bg: #f6f5f2;
  --panel: #ffffff;
  --border: #e2e0da;
  --ink: #262521;
  --muted: #606873;
  --accent: #1d4e89;
  --accent-soft: #e8eef5;
  --shadow: rgba(20, 20, 15, 0.06);
}
:root.night_mode, :root.nightMode, .night_mode, .nightMode {
--bg: #f6f5f2;
  --panel: #ffffff;
  --border: #e2e0da;
  --ink: #262521;
  --muted: #606873;
  --accent: #1d4e89;
  --accent-soft: #e8eef5;
  --shadow: rgba(20, 20, 15, 0.06);
}
.card {
  --bg: #f6f5f2;
  --panel: #ffffff;
  --border: #e2e0da;
  --ink: #262521;
  --muted: #606873;
  --accent: #1d4e89;
  --accent-soft: #e8eef5;
  --shadow: rgba(20, 20, 15, 0.06);

  font-family: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, Roboto, "Noto Sans", sans-serif;
  background-color: var(--bg);
  color: var(--ink);
  text-align: left;
}

.arch-card {
  max-width: 680px;
  margin: 0 auto;
  padding: 28px 16px;
}

.arch-panel {
  background-color: var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  box-shadow: 0 1px 2px var(--shadow), 0 8px 24px var(--shadow);
  padding: 28px 28px 32px;
}

.arch-eyebrow {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 18px;
  text-align: center;
}

.slideshow-container {
  position: relative;
  max-width: 560px;
  margin: 0 auto 20px;
}

.prev, .next {
  display: inline-block;
  color: var(--muted);
  cursor: pointer;
  position: absolute;
  top: 50%;
  user-select: none;
  text-align: center;
  font-size: 18px;
  line-height: 30px;
  width: 30px;
  height: 30px;
  border-radius: 100%;
  background: rgba(255, 255, 255, 0.85);
  border: 1px solid var(--border);
  box-shadow: 0 2px 8px var(--shadow);
  transition: 0.15s ease;
}

.prev { left: 8px; transform: translateY(-50%); }
.next { right: 8px; transform: translateY(-50%); }

.prev:hover, .next:hover {
  color: var(--accent);
  background: #ffffff;
}

.arch-name {
  text-align: center;
  margin-top: 4px;
}

.arch-name > div:first-child {
  font-family: Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman", serif;
  font-size: 22px;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.35;
}

.arch-synonym {
  font-family: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, Roboto, "Noto Sans", sans-serif;
  font-weight: 500;
  font-size: 15px;
  letter-spacing: 0.3px;
  color: var(--muted);
  margin-top: 3px;
}

.arch-focus-value-inline {
  font-family: Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman", serif;
  font-size: 24px;
  font-style: italic;
  font-weight: 700;
  color: var(--accent);
}

.arch-focus-box {
