<script id="qb-mosaic">
(function () {
  var SEL = ".cap-figs, .arch-figs, .arch-concept-figs, .pa-figs, .art-figs, .art-concept-figure, .photo-concept-figure, .qb-figs";
  var HERO_SEL = ".arch-figs";
  var MIN_R = 0.62, MAX_R = 2.4, GAP = 8, ROW_GAP = 6, MIN_H = 230, MAX_H = 300, CAP_H = 44, HERO_MAX = 340, HERO_MAX2 = 440, CAP_D = 54;

  function itemImg(el) { return el.tagName === "IMG" ? el : el.querySelector("img"); }
  function ratioOf(it) {
    var im = itemImg(it);
    var r = im.naturalWidth && im.naturalHeight ? im.naturalWidth / im.naturalHeight : 1;
    return Math.min(MAX_R, Math.max(MIN_R, r));
  }
  var HARD_H = 340;
  function style(it, w, r, h) {
    var im = itemImg(it);
    var nat = im.naturalWidth && im.naturalHeight ? im.naturalWidth / im.naturalHeight : r;
    it.style.flex = "0 0 auto"; it.style.margin = "0";
    it.style.width = w + "px"; it.style.maxWidth = "none";
    im.style.width = (it === im) ? w + "px" : "100%";
    im.style.height = (h || Math.round(w / r)) + "px"; im.style.maxWidth = "100%"; im.style.maxHeight = "none";
    im.style.objectFit = "cover";
    im.style.objectPosition = nat < r ? "50% 12%" : "50% 50%";
  }
  function unwrap(box) {
    if (box._qbCol && box._qbCol.parentNode === box) {
      while (box._qbCol.firstChild) { box.insertBefore(box._qbCol.firstChild, box._qbCol); }
      box.removeChild(box._qbCol);
    }
    box._qbCol = null;
  }

  function heroLayout(box, items, ratios, W) {
    var m = items.length - 1, r0 = ratios[0], S = 0, i, H, heroW, cw, ws = [];
    for (i = 1; i < items.length; i++) { S += 1 / ratios[i]; }
    var avail = W - 2 - GAP;
    if (m === 1) {
      H = Math.min(HERO_MAX, ((avail) / (r0 + 1 / S)) * 1.25);
      heroW = Math.floor(H * r0);
      var room = avail - heroW;
      if (room < 120) { return false; }
      cw = Math.floor(Math.min(room, Math.max(150, heroW * 1.5), 0.62 * H * ratios[1]));
      ws = [cw];
    } else {
      var found = false;
      for (H = HERO_MAX2; H >= 240; H -= 10) {
        heroW = Math.floor(H * r0);
        cw = Math.floor((H + CAP_H - m * CAP_D - (m - 1) * ROW_GAP) / S);
        if (cw >= 130 && heroW + GAP + cw <= avail) { found = true; break; }
      }
      if (!found) { return false; }
      for (i = 1; i < items.length; i++) { ws.push(cw); }
    }
    box.style.flexWrap = "nowrap"; box.style.alignItems = "flex-start"; box.style.justifyContent = "center";
    box.style.columnGap = GAP + "px";
    var col = document.createElement("div");
    col.style.cssText = "display:flex;flex-direction:column;row-gap:" + ROW_GAP + "px;align-items:center;flex:0 0 auto;width:" + cw + "px";
    box.appendChild(col); box._qbCol = col;
    style(items[0], heroW, ratios[0]);
    for (i = 1; i < items.length; i++) { col.appendChild(items[i]); style(items[i], ws[i - 1], ratios[i]); }
    return true;
  }

  function rowsLayout(box, items, ratios, W, forced) {
    var n = items.length, best = forced ? { cost: 0, rows: forced } : null, NARROW = W < 560, MIN_H = NARROW ? Math.min(230, W * 0.5) : 230;
    for (var mask = 0; !forced && mask < (1 << (n - 1)); mask++) {
      var rows = [], cur = [0];
      for (var i = 1; i < n; i++) {
        if (mask & (1 << (i - 1))) { rows.push(cur); cur = [i]; } else { cur.push(i); }
      }
      rows.push(cur);
      var cost = 0, hs = [];
      rows.forEach(function (r) {
        var sum = 0; r.forEach(function (k) { sum += ratios[k]; });
        var h = (W - GAP * (r.length - 1) - 2) / sum, used = Math.min(h, MAX_H);
        cost += used + CAP_H; hs.push(used);
        if (h < MIN_H) { cost += NARROW ? Math.pow(MIN_H - h, 2) / 8 : (MIN_H - h) * 10; }
        if (h > MAX_H) { cost += (1 - MAX_H / h) * 120; }
      });
      var mean = 0; hs.forEach(function (x) { mean += x; }); mean /= hs.length;
      hs.forEach(function (x) { cost += Math.abs(x - mean) * 3; });
      if (!best || cost < best.cost) { best = { cost: cost, rows: rows }; }
    }
    box.style.flexWrap = "wrap"; box.style.alignItems = "flex-start"; box.style.justifyContent = "center";
    box.style.columnGap = GAP + "px"; box.style.rowGap = ROW_GAP + "px";
    var T = W - 2;
    best.rows.forEach(function (r) {
      var sum = 0; r.forEach(function (k) { sum += ratios[k]; });
      T = Math.min(T, HARD_H * sum + GAP * (r.length - 1));
    });
    T = Math.floor(T);
    best.rows.forEach(function (r) {
      var sum = 0; r.forEach(function (k) { sum += ratios[k]; });
      var h = Math.round((T - GAP * (r.length - 1)) / sum), left = T - GAP * (r.length - 1);
      r.forEach(function (k, j) {
        var w = j === r.length - 1 ? left : Math.floor((T - GAP * (r.length - 1)) * ratios[k] / sum);
