  // an image marked data-solo (a handscroll, a panorama) keeps its own row and
  // its own proportions: the row packer would crop it to a 2.4:1 tile
  function isSolo(it) {
    var im = itemImg(it);
    return (it.hasAttribute && it.hasAttribute("data-solo")) || (im && im.hasAttribute("data-solo"));
  }
  function styleSolo(it, W) {
    var im = itemImg(it);
    it.style.flex = "0 0 100%"; it.style.margin = "0";
    it.style.width = W + "px"; it.style.maxWidth = "none";
    im.style.width = "100%"; im.style.height = "auto";
    im.style.maxWidth = "100%"; im.style.maxHeight = "none";
    im.style.objectFit = "contain";
  }
  function layout(box) {
    unwrap(box);
    var all = Array.prototype.slice.call(box.children).filter(function (c) { return itemImg(c); });
    var W = box.clientWidth;
    if (!W) { return; }
    var solo = all.filter(isSolo), items = all.filter(function (c) { return !isSolo(c); });
    if (solo.length) {
      box.style.flexWrap = "wrap"; box.style.alignItems = "flex-start";
      box.style.justifyContent = "center";
      box.style.columnGap = GAP + "px"; box.style.rowGap = ROW_GAP + "px";
      solo.forEach(function (it) { styleSolo(it, W); });
    }
    if (items.length < 2) { return; }
    var ratios = items.map(ratioOf);
    // an image may also name its row (data-row="2"), which pins the grouping
    var tags = items.map(function (it) {
      var im = itemImg(it);
      return (it.getAttribute && it.getAttribute("data-row")) || (im && im.getAttribute("data-row")) || "";
    });
    var forced = null;
    if (tags.some(function (t) { return t; })) {
      forced = []; var cur = [0];
      for (var i = 1; i < items.length; i++) {
        if (tags[i] !== tags[i - 1]) { forced.push(cur); cur = [i]; } else { cur.push(i); }
      }
      forced.push(cur);
    }
    if (!solo.length && !forced && box.matches(HERO_SEL) && items.length >= 2 && W >= 560
        && heroLayout(box, items, ratios, W)) { return; }
    rowsLayout(box, items, ratios, W, forced);
  }

  function run() {
    document.querySelectorAll(SEL).forEach(function (box) {
      var pending = 0;
      box.querySelectorAll("img").forEach(function (im) {
        if (!im.complete) { pending++; im.addEventListener("load", function () { if (--pending === 0) { layout(box); } }); }
      });
      if (!pending) { layout(box); }
    });
  }
  var t;
  (function () { var w0 = window.innerWidth; window.addEventListener("resize", function () { if (Math.abs(window.innerWidth - w0) < 2) { return; } w0 = window.innerWidth; clearTimeout(t); t = setTimeout(run, 120); }); })();
  if (document.readyState === "complete") { run(); } else { window.addEventListener("load", run); }
})();
</script>

<script id="qb-zoom">
(function () {
  if (window.__qbZoomReady) { return; }
  window.__qbZoomReady = true;
  var ov = document.createElement("div");
  ov.style.cssText =
    "position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.88);" +
    "display:none;align-items:center;justify-content:center;z-index:99999;" +
    "cursor:zoom-out;padding:2vmin;";
  var big = document.createElement("img");
  big.style.cssText =
    "max-width:96vw;max-height:96vh;width:auto;height:auto;border:0 !important;" +
    "box-shadow:none !important;background:transparent;object-fit:contain;";
  ov.appendChild(big);
  function close() { ov.style.display = "none"; big.removeAttribute("src"); }
  ov.addEventListener("click", close);
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape") { close(); }
  });
  function attach() {
    if (!document.body) { return; }
    if (!ov.parentNode) { document.body.appendChild(ov); }
    document.addEventListener("click", function (e) {
      var t = e.target;
      if (!t || t.tagName !== "IMG" || t === big) { return; }
      big.src = t.currentSrc || t.src;
      ov.style.display = "flex";
    });
  }
  if (document.body) { attach(); }
  else { document.addEventListener("DOMContentLoaded", attach); }
})();
</script>

<script id="qb-justify">
(function () {
  var SEL = ".arch-figs, .arch-concept-figs, .cap-figs, .art-figs, .art-concept-figure";
  var MAXH = 300, GAP = 10;
  function kids(box) {
    return Array.prototype.filter.call(box.children, function (k) {
      return k.className !== "qb-jbreak" && (k.tagName === "IMG" || (k.querySelector && k.querySelector("img")));
    });
  }
  function img(k) { return k.tagName === "IMG" ? k : k.querySelector("img"); }
  function imp(el, p, v) { el.style.setProperty(p, v, "important"); }
  function lay(box) {
    var ks = kids(box);
    if (ks.length < 2) { return; }
    for (var i = 0; i < ks.length; i++) {
      var m = img(ks[i]);
      if (!m.complete || !m.naturalWidth) { return; }
    }
    var W = box.clientWidth;
    if (!W) { return; }
    // three in a row is too small on a phone: keep one row only while the
    // pictures stay at least MINH tall, else the first alone and two below
    var MINH = 170;
    function rowH(row) {
      var sum = 0;
      row.forEach(function (k) { var m = img(k); sum += m.naturalWidth / m.naturalHeight; });
      return (W - GAP * (row.length - 1) - 2) / sum;
    }
    function split(g) {
      if (g.length < 2) { return g.length ? [g] : []; }
      var rs = g.length === 4 ? [g.slice(0, 2), g.slice(2)] : [g];
      if (g.length === 3 && rowH(g) < MINH) { rs = [g.slice(0, 1), g.slice(1)]; }
      if (g.length > 4 && rowH(g) < MINH) {
        rs = []; for (var r = 0; r < g.length; r += 2) { rs.push(g.slice(r, r + 2)); }
      }
      return rs;
    }
    // a picture marked data-solo (the 5-metre Qingming scroll) gets a full-width row of its own: paired with the
    // next picture it shrank that one to a sliver, its caption running down the card a letter at a time
    var rows = [], seg = [];
    ks.forEach(function (k) {
      var m = img(k);
      if ((k.hasAttribute && k.hasAttribute("data-solo")) || m.hasAttribute("data-solo")) {
        rows = rows.concat(split(seg)); seg = []; rows.push([k]);
      } else { seg.push(k); }
    });
    rows = rows.concat(split(seg));
    imp(box, "display", "flex"); imp(box, "flex-wrap", "wrap"); imp(box, "flex-direction", "row");
    imp(box, "width", "100%");
    imp(box, "justify-content", "center"); imp(box, "align-items", "flex-start");
    imp(box, "gap", "8px " + GAP + "px");
    var brs = box.querySelectorAll(".qb-jbreak"), ok = brs.length === rows.length - 1;
    for (var bi = 0; ok && bi < brs.length; bi++) { ok = brs[bi].nextElementSibling === rows[bi + 1][0]; }
    if (!ok) { Array.prototype.forEach.call(brs, function (x) { x.remove(); }); }
    rows.forEach(function (row, ri) {
      if (ri > 0 && !ok) {
        // force the next row: a zero-height, full-width flex item before it
        var br = document.createElement("div");
        br.className = "qb-jbreak";
        br.style.cssText = "flex:0 0 100% !important;height:0;margin:0;padding:0;";
        box.insertBefore(br, row[0]);
      }
      var sum = 0;
      row.forEach(function (k) { var m = img(k); sum += m.naturalWidth / m.naturalHeight; });
      var h = Math.min(MAXH, (W - GAP * (row.length - 1) - 2) / sum);
      row.forEach(function (k) {
        var m = img(k), w = Math.floor(h * m.naturalWidth / m.naturalHeight);
        imp(k, "flex", "0 0 " + w + "px"); imp(k, "width", w + "px"); imp(k, "max-width", "none");
        imp(k, "min-width", "0"); imp(k, "margin", "0");
        if (k !== m) { imp(m, "width", "100%"); }
        else { imp(m, "width", w + "px"); }
        imp(m, "height", "auto"); imp(m, "max-height", "none"); imp(m, "max-width", "100%");
        imp(m, "background", "none");
      });
    });
  }
  function all() { Array.prototype.forEach.call(document.querySelectorAll(SEL), lay); }
  all();
  Array.prototype.forEach.call(document.querySelectorAll(SEL + " img"), function (m) {
    if (!m.complete) { m.addEventListener("load", all); }
  });
  (function () { var w0 = window.innerWidth; window.addEventListener("resize", function () { if (Math.abs(window.innerWidth - w0) < 2) { return; } w0 = window.innerWidth; all(); }); })();
  // the Art caption script rebuilds the figures after load, wiping these widths:
  // lay out again whenever a picture block gains new children (not our breaks)
  var pend = null;
