Classical Music.css:
/* Classical Music */
:root {
  --bg: #f6f5f2;
  --panel: #ffffff;
  --border: #e7ddda;
  --ink: #2a2320;
  --muted: #7b6260;
  --accent: #a63d2f;
  --accent-soft: #f7ece9;
  --shadow: rgba(30, 20, 15, 0.06);
}
:root.night_mode, :root.nightMode, .night_mode, .nightMode {
--bg: #f6f5f2;
  --panel: #ffffff;
  --border: #e7ddda;
  --ink: #2a2320;
  --muted: #7b6260;
  --accent: #a63d2f;
  --accent-soft: #f7ece9;
  --shadow: rgba(30, 20, 15, 0.06);
}
.card {
  --bg: #f6f5f2;
  --panel: #ffffff;
  --border: #e7ddda;
  --ink: #2a2320;
  --muted: #7b6260;
  --accent: #a63d2f;
  --accent-soft: #f7ece9;
  --shadow: rgba(30, 20, 15, 0.06);

  font-family: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, Roboto, "Noto Sans", sans-serif;
  background-color: var(--bg);
  color: var(--ink);
  text-align: center;
}

.qb-card {
  max-width: 620px;
  margin: 0 auto;
  padding: 40px 22px 48px;
}

.qb-panel {
  background-color: var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  box-shadow: 0 1px 2px var(--shadow), 0 8px 24px var(--shadow);
  padding: 32px 28px 34px;
}

.qb-eyebrow {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 26px;
}

.qb-audio {
  margin-bottom: 4px;
}

.qb-focus-box {
  margin-top: 30px;
  background-color: var(--accent-soft);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 20px 24px;
}

.qb-focus-label {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--muted);
}

.qb-focus-value {
  font-family: Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman", serif;
  font-size: 22px;
  font-weight: 700;
  color: var(--accent);
  margin-top: 8px;
  line-height: 1.4;
}

.qb-dates {
  font-size: 15px;
  font-weight: 500;
  color: var(--muted);
  margin-top: 9px;
}

.qb-work {
  font-family: Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman", serif;
  font-size: 20px;
  font-weight: 600;
  font-style: italic;
  color: var(--ink);
  margin-top: 26px;
  line-height: 1.55;
}

.qb-nickname {
  display: block;
  margin-top: 6px;
  font-family: Georgia, "Iowan Old Style", "Palatino Linotype",
               "Times New Roman", serif;
  font-size: 20px;
  font-weight: 600;
  font-style: italic;
  color: var(--ink);
}

.qb-movement {
  font-family: Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman";
  font-size: 18px;
  font-weight: 500;
  color: var(--ink);
  margin-top: 18px;
  line-height: 1.5;
}

.qb-facts {
  margin-top: 34px;
  padding-top: 24px;
  border-top: 1px solid var(--border);
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(118px, 1fr));
  gap: 18px 26px;
  align-items: start;
  text-align: center;
  margin-bottom: 22px;
}

.qb-fact {
  min-width: 60px;
  min-width: 0;
  overflow-wrap: anywhere;
}

.qb-fact-label {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

.qb-fact-value {
  margin-top: 3px;
  font-size: 15px;
  font-weight: 600;
  color: var(--ink);
}

.night_mode .card, .nightMode .card {
--bg: #f6f5f2;
