  window.__qbZoomReady = true;
  var ov = document.createElement("div");
  ov.style.cssText =
    "position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.88);" +
    "display:none;align-items:center;justify-content:center;z-index:99999;" +
    "cursor:zoom-out;padding:2vmin;";
  var big = document.createElement("img");
  big.style.cssText =
    "max-width:96vw;max-height:96vh;width:auto;height:auto;border:0 !important;" +
    "box-shadow:none !important;background:transparent;object-fit:contain;";
  ov.appendChild(big);
  function close() { ov.style.display = "none"; big.removeAttribute("src"); }
  ov.addEventListener("click", close);
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape") { close(); }
  });
  function attach() {
    if (!document.body) { return; }
    if (!ov.parentNode) { document.body.appendChild(ov); }
    document.addEventListener("click", function (e) {
      var t = e.target;
      if (!t || t.tagName !== "IMG" || t === big) { return; }
      big.src = t.currentSrc || t.src;
      ov.style.display = "flex";
    });
  }
  if (document.body) { attach(); }
  else { document.addEventListener("DOMContentLoaded", attach); }
})();
</script>
<script id="qb-scroll-answer">
(function () {
