  var stopped = false;
  function answerEl() {
    var el = document.querySelector(SEL);
    if (el) { return el; }
    var hr = document.querySelector("hr");
    return hr ? (hr.nextElementSibling || hr) : null;
  }
  function place() {
    if (stopped) { return; }
    var el = answerEl();
    if (!el) { return; }
    var top = el.getBoundingClientRect().top + window.pageYOffset;
    var want = Math.max(0, Math.round(top - window.innerHeight * 0.28));
    var img = document.querySelector("img");
    if (img) {
      var it = img.getBoundingClientRect().top + window.pageYOffset;
      want = Math.min(want, Math.max(0, Math.round(it - 12)));
    }
    window.scrollTo(0, want);
  }
  ["wheel", "touchstart", "keydown", "mousedown"].forEach(function (ev) {
    window.addEventListener(ev, function () { stopped = true; }, { passive: true, once: true });
  });
  place();
  window.addEventListener("load", place);
  Array.prototype.forEach.call(document.images, function (im) {
    if (!im.complete) { im.addEventListener("load", place); }
  });
  [120, 400, 900, 1600].forEach(function (t) { setTimeout(place, t); });
})();
</script>

