Film.css:
/* Film */
:root {
  --bg: #f6f5f2;
  --panel: #ffffff;
  --border: #dde2e1;
  --ink: #1f2624;
  --muted: #64716e;
  --accent: #1f5f5b;
  --accent-soft: #eaf2f1;
  --shadow: rgba(15, 30, 28, 0.06);
}
.card {
  --bg: #f6f5f2;
  --panel: #ffffff;
  --border: #dde2e1;
  --ink: #1f2624;
  --muted: #64716e;
  --accent: #1f5f5b;
  --accent-soft: #eaf2f1;
  --shadow: rgba(15, 30, 28, 0.06);

  font-family: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, Roboto,
               "Noto Sans", sans-serif;
  background-color: var(--bg);
  color: var(--ink);
  text-align: center;
}
html, body { background-color: var(--bg); }

:root.night_mode, :root.nightMode, html:has(> body.night_mode), html:has(> body.nightMode), .night_mode, .nightMode, .night_mode .card, .nightMode .card {
  --bg: #17181a;
  --panel: #202226;
  --border: #343b3a;
  --ink: #e7e5df;
  --muted: #a3afac;
  --accent: #8fc3bd;
  --accent-soft: #1d2b2a;
  --shadow: rgba(0, 0, 0, 0.45);
}
:root.night_mode, :root.nightMode, html:has(> body.night_mode), html:has(> body.nightMode), .night_mode, .nightMode, .night_mode .card, .nightMode .card, body.night_mode, body.nightMode {
  background-color: var(--bg) !important;
  color: var(--ink) !important;
}

.qb-card { max-width: 640px; margin: 0 auto; padding: 36px 20px 44px; }
.qb-panel { background-color: transparent; border: none; padding: 6px 4px 14px; }

.qb-eyebrow {
  font-size: 13px; font-weight: 700; letter-spacing: 2.5px;
  text-transform: uppercase; color: var(--muted); margin-bottom: 24px;
}

.film-clue {
  font-family: Georgia, "Iowan Old Style", "Palatino Linotype",
               "Times New Roman", serif;
  font-size: 19px; line-height: 1.65; color: var(--ink);
  text-align: left; margin: 0 auto 8px; max-width: 580px;
}
.film-ask {
  font-size: 23px; font-weight: 500; color: var(--accent);
  margin-top: 26px; padding-top: 18px; border-top: 1px solid var(--border);
}
.film-title {
  font-family: Georgia, "Iowan Old Style", "Palatino Linotype",
               "Times New Roman", serif;
  font-size: 29px; font-weight: 700; font-style: italic; color: var(--ink);
  line-height: 1.35; margin-top: 4px;
}
.film-orig {
  font-family: Georgia, "Iowan Old Style", "Palatino Linotype",
               "Times New Roman", serif;
  font-size: 19px; font-style: italic; color: var(--muted); margin-top: 7px;
}
.film-credit { font-size: 18px; color: var(--ink); margin-top: 16px; }
.film-credit b { font-weight: 600; }
.film-meta { font-size: 15px; color: var(--muted); margin-top: 8px; }

.film-label {
  font-size: 12px; font-weight: 700; letter-spacing: .14em;
  text-transform: uppercase; color: var(--muted);
  margin: 22px auto 4px; max-width: 580px; text-align: left;
}
.film-note {
  font-size: 16.5px; line-height: 1.55; color: var(--ink);
  text-align: left; margin: 0 auto; max-width: 580px;
}

.film-figs { margin: 0 auto 6px; }
.film-figs img {
  display: block; margin: 0 auto; max-width: 100%; max-height: 380px;
  border-radius: 10px; box-shadow: 0 1px 2px var(--shadow), 0 8px 24px var(--shadow);
}
.film-poster img { max-height: 420px; }
.film-cap {
  font-size: 14px; color: var(--muted); margin-top: 9px; font-style: italic;
}
img { cursor: zoom-in; }

.film-tier { margin-top: 20px; text-align: center; }
.film-tier .custom-tag {
  display: inline-block; font-size: 12px; font-weight: 600; letter-spacing: 1px;
  text-transform: uppercase; color: var(--muted); border: 1px solid var(--border);
  border-radius: 999px; padding: 3px 12px;
}

@media (max-width: 480px) {
  .qb-card { padding: 24px 14px 32px; }
  .film-clue { font-size: 17.5px; }
  .film-title { font-size: 25px; }
}

.film-gallery {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
  gap: 14px; align-items: start; margin: 22px auto 4px; max-width: 620px;
}
.film-fig { margin: 0; }
.film-fig img {
  display: block; width: 100%; height: auto; max-height: 300px;
  object-fit: contain; border-radius: 10px;
  box-shadow: 0 1px 2px var(--shadow), 0 8px 24px var(--shadow);
}
.film-fig figcaption {
  font-size: 13px; line-height: 1.4; color: var(--muted);
  margin-top: 7px; text-align: left;
}
.film-fig-poster img { max-height: 340px; }
@media (max-width: 480px) {
  .film-gallery { grid-template-columns: 1fr; }
}

/* 2026-09-27: same framing as the other decks -- square corners, 1px black border */
.film-figs img, .film-fig img { border-radius: 0 !important; border: 1px solid #000 !important; box-sizing: border-box; }

/* 2026-09-27: an odd last picture is centred, not left in the first column (checklist A15) */
.film-gallery { display: flex !important; flex-wrap: wrap; justify-content: center; }
.film-gallery > .film-fig { flex: 0 1 calc(50% - 7px); min-width: 0; }
@media (max-width: 520px) { .film-gallery > .film-fig { flex-basis: 100%; } }
.film-fig figcaption { text-align: center; }

/* 2026-09-27: the frame hugs the picture instead of a letterboxed column */
.film-fig img { width: auto !important; max-width: 100% !important; margin: 0 auto; }

/* qb-tier-pill 2026-09-28: the tier label drawn like the Art Hint button */
#allowed-tags-container .custom-tag, .qb-tier .custom-tag, .arch-tier .custom-tag,
.film-tier .custom-tag, .pa-tier .custom-tag, .photo-tier .custom-tag {
  display: inline-block !important; padding: 5px 16px !important; margin-top: 0 !important;
  border: 1px solid #c9bca6 !important; border-radius: 16px !important; background: none !important;
  font-family: Optima, "Century Gothic", sans-serif !important; font-size: 14px !important;
  font-weight: 400 !important; line-height: 1.4 !important; letter-spacing: 0.12em !important;
  text-transform: uppercase !important; color: #6b4c3b !important; box-shadow: none !important; }
:is(.night_mode, .nightMode) :is(#allowed-tags-container, .qb-tier, .arch-tier, .film-tier, .pa-tier, .photo-tier) .custom-tag {
  border-color: #555 !important; color: #aaa !important; }
/* /qb-tier-pill */

/* film_tmpl_1001: answer in the accent colour, a labelled facts grid, centred sections, a smaller poster */
.film-prompt-back { color: var(--muted) !important; font-size: 16.5px !important; line-height: 1.55 !important; }
.film-title.film-prompt-back, .film-name.film-prompt-back { font-size: 22px !important; }
.film-divider { border: none; border-top: 1px solid var(--border); margin: 22px auto 20px; max-width: 580px; }
.film-name { font-family: Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman", serif;
  font-size: 27px; font-weight: 700; color: var(--ink); line-height: 1.3; }
.film-answer { font-family: Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman", serif;
  font-size: 27px; font-weight: 700; line-height: 1.3; }
.film-hit { color: var(--accent) !important; }
.film-works { font-family: Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman", serif;
  font-size: 21px; font-weight: 600; line-height: 1.45; max-width: 30em; margin: 0 auto; }
.film-orig { font-size: 17px !important; margin-top: 4px !important; }
.film-facts { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px 32px; margin: 18px auto 0; max-width: 36em; }
.film-facts:not(:has(.film-fact)) { display: none; }
.film-fact { min-width: 84px; max-width: 240px; }
.film-fact-label { font-size: 12px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--muted); }
.film-fact-value { font-size: 15px; font-weight: 600; line-height: 1.4; color: var(--ink); margin-top: 3px; overflow-wrap: anywhere; }
.film-chip { display: inline-block; margin-top: 14px; padding: 3px 12px; border: 1px solid var(--border); border-radius: 999px;
  font-size: 13px; color: var(--muted); }
.film-section { margin: 20px auto 0; max-width: 34em; padding-top: 14px; border-top: 1px solid var(--border); text-align: center; }
.film-section .film-label { margin: 0 0 6px; text-align: center !important; }
.film-note { text-align: center !important; font-size: 16px !important; line-height: 1.6 !important; }
.film-gallery { margin-top: 20px !important; gap: 12px !important; }
.film-gallery:empty { display: none; }
.film-fig img { max-height: 300px !important; }
.film-fig-poster img { max-height: 230px !important; }
.film-fig figcaption { text-align: center !important; font-size: 12.5px !important; }
.film-portrait { margin-top: 20px; }
.film-portrait img { max-height: 300px !important; }
.film-figs img { border-radius: 0 !important; border: 1px solid #000 !important; }
.film-cap { font-style: normal !important; }
@media (max-width: 480px) { .film-answer, .film-name { font-size: 24px; } .film-works { font-size: 19px; } }
/* /film_tmpl_1001 */

