<script id="qb-geo-hint">
(function () {
  var box = document.querySelector(".geo-hint");
  if (!box || box.getAttribute("data-ready")) { return; }
  box.setAttribute("data-ready", "1");
  var parts = (box.querySelector(".geo-hint-data").textContent || "").split("##");
  var raw = box.getAttribute("data-card") === "photo" && parts.length > 1 ? parts[1] : parts[0];
  var tiers = raw.split("|").map(function (s) { return s.trim(); }).filter(function (s) { return s; })
    .map(function (s) {
      var m = s.match(/^([A-Za-z ]+)::(.+)$/);
      return m ? { label: m[1], text: m[2] } : { label: "Region", text: s };
    });
  var btn = box.querySelector(".geo-hint-btn");
  var out = box.querySelector(".geo-hint-text");
  var shown = 0;
  if (!tiers.length) { box.hidden = true; return; }
  btn.textContent = tiers[0].label;
  btn.addEventListener("click", function (e) {
    e.preventDefault();
    e.stopPropagation();
    shown = Math.min(shown + 1, tiers.length);
    out.textContent = tiers.slice(0, shown).map(function (t) {
      return t.label === "Capital" ? "Capital: " + t.text : t.text;
    }).join("  \u00b7  ");
    if (shown >= tiers.length) { btn.hidden = true; return; }
    btn.textContent = tiers[shown].label;
  });
})();
</script>

