Geography.css:
/* Geography */
:root {
font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  background-color: var(--bg);
  color: var(--ink);
  text-align: center;
  -webkit-font-smoothing: antialiased;
}

.card {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  background-color: var(--bg);
  color: var(--ink);
  text-align: center;
  -webkit-font-smoothing: antialiased;
}
html { background-color: transparent; }
body { background-color: var(--bg); }

.geo-card {
  max-width: 840px;
  margin: 0 auto;
  padding: 38px 22px 46px;
}

.geo-eyebrow {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--faint);
  margin-bottom: 22px;
}

.geo-map img,
.geo-photo img,
.geo-flag img {
  display: block;
  margin: 0 auto;
  width: auto;
  height: auto;
  object-fit: contain;
  background: var(--surface);
  border: 1px solid var(--border);
  box-shadow: 0 1px 2px rgba(20, 30, 25, 0.05), 0 10px 28px rgba(20, 30, 25, 0.06);
  image-rendering: -webkit-optimize-contrast;
}
.geo-flag img  { max-width: min(100%, 640px); max-height: 40vh; padding: 0; }
.geo-photo { margin-top: 22px; }

.geo-divider {
  border: none;
  border-top: 1px solid var(--rule);
  width: 46%;
  max-width: 260px;
  margin: 28px auto 24px;
  opacity: 0.85;
}

.geo-name {
  font-family: Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman", serif;
  font-size: 30px;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: 0.01em;
}
.geo-alt {
  font-size: 16px;
  color: var(--muted);
  margin-top: 6px;
  font-style: italic;
}

.geo-focus {
  display: inline-block;
  min-width: 46%;
  margin-top: 24px;
  background: var(--accent-soft);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 16px 30px;
}
.geo-focus-label {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}
.geo-focus-value {
  font-family: Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman", serif;
  font-size: 26px;
  font-weight: 700;
  color: var(--accent);
  margin-top: 6px;
  line-height: 1.3;
}

.geo-meta {
  margin-top: 22px;
  font-size: 15px;
  color: var(--muted);
  line-height: 1.75;
}
.geo-info {
  margin-top: 18px;
  font-size: 16px;
  color: var(--ink);
  text-align: left;
  display: inline-block;
  max-width: 36em;
  line-height: 1.65;
}

.geo-meta:empty, .geo-alt:empty, .geo-info:empty { display: none; }
.geo-alt-label {
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 12px;
  font-style: normal;
  color: var(--muted);
  margin-right: 4px;
}

.night_mode, .nightMode,
:root.night_mode, :root.nightMode {
font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  background-color: var(--bg);
  color: var(--ink);
  text-align: center;
  -webkit-font-smoothing: antialiased;
}
.night_mode, .nightMode,
.night_mode html, .night_mode body, .night_mode .card,
.nightMode html, .nightMode body, .nightMode .card {
font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  background-color: var(--bg);
  color: var(--ink);
  text-align: center;
  -webkit-font-smoothing: antialiased;
}

.night_mode .geo-map img, .nightMode .geo-map img,
.night_mode .geo-flag img, .nightMode .geo-flag img {}
.night_mode .geo-photo img, .nightMode .geo-photo img {}

.geo-map {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 10px;
}
.geo-map img {
  box-sizing: border-box;
  flex: 0 1 calc(50% - 6px);
  max-width: calc(50% - 6px);
  max-height: 46vh;
  width: auto; height: auto;
  object-fit: contain;
  padding: 4px;
}
.geo-map img:only-child {
  flex: 0 1 auto;
  max-width: min(100%, 820px);
  max-height: 52vh;
}

.geo-photo img {
  max-width: min(100%, 760px);
  max-height: 44vh;
  padding: 0;
}

.geo-facts {
  margin-top: 24px;
  padding-top: 20px;
  border-top: 1px solid var(--border);
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(112px, 1fr));
  gap: 16px 24px;
  align-items: start;
  text-align: center;
  margin-bottom: 22px;
}
.geo-fact { min-width: 0; overflow-wrap: anywhere; }
.geo-fact-label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}
.geo-fact-value {
  margin-top: 3px;
  font-size: 15px;
  font-weight: 600;
  color: var(--ink);
}
.geo-facts:empty { display: none; }

.geo-focus + .geo-alt { margin-top: 14px; }

.geo-map img { flex: 1 1 calc(50% - 6px); max-width: calc(50% - 6px);
               height: 300px; object-fit: contain; }
.geo-map img:only-child { flex: 0 1 auto; max-width: min(100%, 820px);
                          height: auto; max-height: 52vh; }
.geo-photo { margin-top: 26px; }
.geo-photo img { max-width: min(100%, 820px); max-height: 50vh; }

img { cursor: zoom-in; }

.art-figs, .qb-figs, .pa-figs {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 8px;
  align-items: center;
  justify-items: center;
  margin: 6px 0 16px;
}
.art-figs img, .qb-figs img, .pa-figs img {
  width: 100%;
  height: 300px;
  object-fit: contain;
  display: block !important;
}

.geo-photo-caption {
  margin-top: 6px; font-size: 13px; line-height: 1.4;
  color: var(--muted); text-align: center;
}
.geo-pron {
  margin-top: 4px; font-size: 15px; color: var(--muted);
  font-family: "Segoe UI", system-ui, sans-serif;
}

.geo-info ul { margin: 0; padding-left: 20px; text-align: left; }
.geo-info li { margin: 4px 0; line-height: 1.5; }

.geo-facts { max-width: 720px; margin-left: auto; margin-right: auto;
             grid-template-columns: repeat(auto-fit, minmax(120px, 180px));
             justify-content: center; }

.card img, img { border: 1px solid #000 !important; box-sizing: border-box; }

#allowed-tags-container { text-align: center !important; margin-top: 18px; }
#allowed-tags-container .custom-tag {
