.geo-hint-btn:hover { color: var(--ink, #1e2723); border-color: var(--muted, #6b7a73); }
.geo-hint-btn[hidden] { display: none; }
.geo-hint-text { font-size: 17px; font-weight: 600; line-height: 1.4; color: var(--ink, #1e2723);
