<script id="qb-front-caps-js">
(function () {
  var data = document.getElementById("qb-front-caps");
  var eyebrow = document.querySelector(".arch-concept-eyebrow");
  var box = document.querySelector(".arch-concept-figs");
  var def = document.querySelector(".arch-concept-def");
  if (!data || !box || !def || !eyebrow) { return; }
  var name = (document.getElementById("qb-front-name").textContent || "").toLowerCase();
  var nameBits = name.split(/[\s\-]+/).filter(function (w) { return w.length >= 3; });
  var text = (def.textContent || "").toLowerCase();
  var caps = data.querySelectorAll("span");
  var imgs = box.querySelectorAll("img");
  for (var i = 0; i < imgs.length && i < caps.length; i++) {
    var work = (caps[i].textContent || "").split(/,|\(|\s[–—-]\s/)[0].trim();
    var low = work.toLowerCase().replace(/^(the|a|an)\s+/, "");
    var alts = [low], pos = low.indexOf("'s "), pos2 = low.indexOf("’s ");
    if (pos > 0) { alts.push(low.slice(pos + 3)); }
    if (pos2 > 0) { alts.push(low.slice(pos2 + 3)); }
    var hit = alts.filter(function (a) { return a.length >= 4 && text.indexOf(a) >= 0; })[0];
    if (!hit) { continue; }
    low = hit;
    if (nameBits.some(function (b) { return low.indexOf(b) >= 0; })) { continue; }
    var fig = document.createElement("figure");
    fig.className = "arch-fig";
    imgs[i].parentNode.insertBefore(fig, imgs[i]);
    fig.appendChild(imgs[i]);
    var cap = document.createElement("figcaption");
    cap.textContent = work;
    fig.appendChild(cap);
  }
})();
</script>

