}
/* on the answer side it becomes a caption over the answer */
.hist-prompt-back {
  font-size: 14.5px;
  line-height: 1.5;
  color: var(--faint);
  max-width: 540px;
}

.hist-atomic .hist-divider {
  border: none;
  border-top: 1px solid var(--rule);
  width: 34%;
  max-width: 180px;
  margin: 26px auto 26px;
}

.hist-answer {
  font-family: Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman", serif;
  font-size: 32px;
  font-weight: 700;
  line-height: 1.3;
  color: var(--accent);
}
.hist-answer i, .hist-answer em { font-style: italic; }

/* read after answering, so it is set apart and never reads as part of the
   thing you were meant to recall */
.hist-extra {
  font-size: 15px;
  line-height: 1.62;
  color: var(--muted);
  max-width: 500px;
  margin: 22px auto 0;
  padding: 0 0 0 16px;
  text-align: left;
  border-left: 2px solid var(--border);
}

/* pictures sit on a plate, as the artworks do in the Art deck */
.hist-photo, .hist-map { margin-top: 30px; }
.hist-photo img, .hist-map img {
  display: block;
  margin: 0 auto;
  max-width: min(100%, 430px);
  max-height: 38vh;
  width: auto;
  height: auto;
  object-fit: contain;
  background: var(--plate);
  padding: 6px;
  border: 1px solid var(--border);
  box-shadow: 0 1px 2px var(--shadow), 0 10px 26px var(--shadow);
  cursor: zoom-in;
}

/* the entity, as a quiet chip -- the Art deck marks its tiers the same way */
.hist-entity {
  display: inline-block;
  margin-top: 30px;
  padding: 5px 14px;
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--faint);
  background: var(--plate);
  border: 1px solid var(--border);
  border-radius: 999px;
}

/* qb-tier-pill 2026-09-28: the tier label drawn like the Art Hint button */
#allowed-tags-container .custom-tag, .qb-tier .custom-tag, .arch-tier .custom-tag,
.film-tier .custom-tag, .pa-tier .custom-tag, .photo-tier .custom-tag {
  display: inline-block !important; padding: 5px 16px !important; margin-top: 0 !important;
  border: 1px solid #c9bca6 !important; border-radius: 16px !important; background: none !important;
  font-family: Optima, "Century Gothic", sans-serif !important; font-size: 14px !important;
  font-weight: 400 !important; line-height: 1.4 !important; letter-spacing: 0.12em !important;
  text-transform: uppercase !important; color: #6b4c3b !important; box-shadow: none !important; }
:is(.night_mode, .nightMode) :is(#allowed-tags-container, .qb-tier, .arch-tier, .film-tier, .pa-tier, .photo-tier) .custom-tag {
  border-color: #555 !important; color: #aaa !important; }
/* /qb-tier-pill */

/* phone-bar 2026-10-01: room under the last line for AnkiMobile's answer bar, and no rubber-band bounce past the page's ends (Carter) */
.card { padding-bottom: 110px !important; }
html, body { overscroll-behavior-y: none; }

