.list2-rank { font-weight: 800; font-size: 14px; color: #ffffff; background: #b7a582; width: 26px; height: 26px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex: none; }
.list2-thumb { width: 118px; height: 78px; flex: none; border-radius: 7px; overflow: hidden; background: #efe9d8; box-shadow: 0 1px 3px rgba(20,30,25,.12); }
.list2-thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
.list2-name { flex: 1 1 auto; min-width: 0; font-size: 16.5px; font-weight: 700; line-height: 1.25; color: #23231f; }
.list2-stat { flex: none; font-size: 13.5px; font-weight: 600; color: #8a8a7e; text-align: right; max-width: 30vw; white-space: normal; overflow-wrap: break-word; font-variant-numeric: tabular-nums; }
.list2-row.is-blank { background: repeating-linear-gradient(135deg, #f4f2ea, #f4f2ea 9px, #edeadf 9px, #edeadf 18px); border-style: dashed; }
