Photography.css:
/* Photography */
:root {
  --bg: #f4f5f3;
  --panel: #ffffff;
  --border: #dde1de;
  --ink: #212422;
  --muted: #616967;
  --accent: #2b6e63;
  --accent-soft: #e7f1ef;
  --shadow: rgba(15, 20, 18, 0.06);
}
:root.night_mode, :root.nightMode, .night_mode, .nightMode {
--bg: #f4f5f3;
  --panel: #ffffff;
  --border: #dde1de;
  --ink: #212422;
  --muted: #616967;
  --accent: #2b6e63;
  --accent-soft: #e7f1ef;
  --shadow: rgba(15, 20, 18, 0.06);
}
.card {
  --bg: #f4f5f3;
  --panel: #ffffff;
  --border: #dde1de;
  --ink: #212422;
  --muted: #616967;
  --accent: #2b6e63;
  --accent-soft: #e7f1ef;
  --shadow: rgba(15, 20, 18, 0.06);

  font-family: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, Roboto, "Noto Sans", sans-serif;
  background-color: var(--bg);
  color: var(--ink);
  text-align: center;
}

.qb-card {
  max-width: 640px;
  margin: 0 auto;
  padding: 28px 16px;
}

.qb-panel {
  background-color: var(--panel);
  border: 1px solid var(--border);
